-- Canonical acquisition timestamps, including fractional seconds and UTC offsets.
-- Separate integer seconds/nanoseconds avoid float precision loss and epoch overflow.
CREATE INDEX work_contracts_workspace_acquired ON work_contracts(namespace_id,outcome_id,work_item_id,(((make_date(CASE WHEN CAST(substr((state_json::jsonb ->> 'acquired_at'),1,4) AS INTEGER)=0 THEN -1 ELSE CAST(substr((state_json::jsonb ->> 'acquired_at'),1,4) AS INTEGER) END,CAST(substr((state_json::jsonb ->> 'acquired_at'),6,2) AS INTEGER),CAST(substr((state_json::jsonb ->> 'acquired_at'),9,2) AS INTEGER))-DATE '1970-01-01')::bigint*86400+CAST(substr((state_json::jsonb ->> 'acquired_at'),12,2) AS bigint)*3600+CAST(substr((state_json::jsonb ->> 'acquired_at'),15,2) AS bigint)*60+CAST(substr((state_json::jsonb ->> 'acquired_at'),18,2) AS bigint)-(CASE WHEN right((state_json::jsonb ->> 'acquired_at'),1)='Z' THEN 0 ELSE (CASE WHEN substr(right((state_json::jsonb ->> 'acquired_at'),6),1,1)='+' THEN 1 ELSE -1 END)*(CAST(substr(right((state_json::jsonb ->> 'acquired_at'),6),2,2) AS bigint)*3600+CAST(substr(right((state_json::jsonb ->> 'acquired_at'),6),5,2) AS bigint)*60) END))) DESC,(CASE WHEN substr((state_json::jsonb ->> 'acquired_at'),20,1)='.' THEN CAST(substr(substr((state_json::jsonb ->> 'acquired_at'),21,length((state_json::jsonb ->> 'acquired_at'))-20-(CASE WHEN right((state_json::jsonb ->> 'acquired_at'),1)='Z' THEN 1 ELSE 6 END))||'000000000',1,9) AS INTEGER) ELSE 0 END) DESC,id DESC);
CREATE INDEX signed_work_contracts_workspace_acquired ON signed_work_contracts(namespace_id,outcome_id,work_item_id,(((make_date(CASE WHEN CAST(substr((state_json::jsonb ->> 'acquired_at'),1,4) AS INTEGER)=0 THEN -1 ELSE CAST(substr((state_json::jsonb ->> 'acquired_at'),1,4) AS INTEGER) END,CAST(substr((state_json::jsonb ->> 'acquired_at'),6,2) AS INTEGER),CAST(substr((state_json::jsonb ->> 'acquired_at'),9,2) AS INTEGER))-DATE '1970-01-01')::bigint*86400+CAST(substr((state_json::jsonb ->> 'acquired_at'),12,2) AS bigint)*3600+CAST(substr((state_json::jsonb ->> 'acquired_at'),15,2) AS bigint)*60+CAST(substr((state_json::jsonb ->> 'acquired_at'),18,2) AS bigint)-(CASE WHEN right((state_json::jsonb ->> 'acquired_at'),1)='Z' THEN 0 ELSE (CASE WHEN substr(right((state_json::jsonb ->> 'acquired_at'),6),1,1)='+' THEN 1 ELSE -1 END)*(CAST(substr(right((state_json::jsonb ->> 'acquired_at'),6),2,2) AS bigint)*3600+CAST(substr(right((state_json::jsonb ->> 'acquired_at'),6),5,2) AS bigint)*60) END))) DESC,(CASE WHEN substr((state_json::jsonb ->> 'acquired_at'),20,1)='.' THEN CAST(substr(substr((state_json::jsonb ->> 'acquired_at'),21,length((state_json::jsonb ->> 'acquired_at'))-20-(CASE WHEN right((state_json::jsonb ->> 'acquired_at'),1)='Z' THEN 1 ELSE 6 END))||'000000000',1,9) AS INTEGER) ELSE 0 END) DESC,id DESC);
